const cmds = [
  '"$HORIZON_BIN" search "open immersion descend faithfully flat base change" --json',
  '"$HORIZON_BIN" search "IsOpenImmersion fpqc" --json',
  '"$HORIZON_BIN" search "open immersion is local at target" --json',
  '"$HORIZON_BIN" search "IsOpenImmersion baseChange" --json'
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:12000})));
rs.forEach((r,i)=>{ text(`QUERY ${i+1}\n${r.output}`); });

const rs = await Promise.all([
  tools.exec_command({cmd:"sed -n '160,205p' /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry/Restrict.lean && sed -n '555,585p' /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry/Restrict.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"sed -n '35,150p' /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry/Gluing.lean && sed -n '250,355p' /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry/Gluing.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({cmd:"sed -n '35,150p' /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry/Cover/Open.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"rg -n \"\\.gluedCover\\.V|gluedCover_V|IsAffine.*\\.V|isoPullback\\.inv\" /home/axel/LeanAlgebraicGeometry-Horizon -g '*.lean' | head -200","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":20000})
]); rs.forEach((r,i)=>text(`RESULT ${i+1}\n${r.output}`));

const qs = [
 "a scheme morphism is an open immersion if after faithfully flat base change it is an open immersion",
 "open immersion descends along surjective flat morphism of schemes",
 "IsOpenImmersion fpqc local on target",
 "scheme morphism property open immersion descent"
];
const rs = [];
for (const q of qs) rs.push(await tools.mcp__lean_lsp__lean_leansearch({query:q,num_results:10}));
rs.forEach((r,i)=>{ text(`Q${i+1}`); text(r); });

const rs = await Promise.all([
  tools.exec_command({cmd:"rg -n \"def IsOpenCover|structure IsOpenCover|class IsOpenCover|abbrev IsOpenCover\" /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib -g '*.lean' | head -80","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"rg -n \"openCoverOfIsOpenCover.*pic0|openCoverOfIsOpenCover\" AlgebraicJacobian -g '*.lean' | head -100","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"rg -n \"IsAffine\\.of_isIso|instance.*IsAffine.*iso|IsAffine.of_isIso\" /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry -g '*.lean' | head -100","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"sed -n '430,455p' /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/AlgebraicGeometry/ProjectiveSpectrum/Basic.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":10000,"max_output_tokens":10000})
]); rs.forEach((r,i)=>text(`RESULT ${i+1}\n${r.output}`));

